## Code Example
```javascript
// Pseudocode for Cloud Function
exports.dlpScan = (event, context) => {
  const file = event.name;
  const result = dlp.inspect(file);
  const dest = result.secretsFound ? quarantinePath(file) : processedPath(file);
  copyTo(dest);
  logToBigQuery({ file, date: today(), secretsFound: result.secretsFound });
};
```

